{"hypotheses": [
  {
    "name": "Strategic Buyback–R&D Allocation",
    "mechanism": "Firms that simultaneously engage in share repurchases and maintain above-average R&D intensity are likely exploiting undervaluation while supporting future growth, signaling superior capital allocation. The blend captures a distinct premium not explained by either action alone, as it screens for firms avoiding short-termism and financial engineering.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ShareRepurchase"},
        {"weight": 0.5, "primitive": "RDcap"},
        {"weight": -0.5, "primitive": "NetEquityFinance"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "ShareRepurchase", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Supply Chain Insider Advantage",
    "mechanism": "Firms that benefit from both strong customer momentum and positive analyst revisions in their supply chain are likely to have unique forward-looking information advantages, which neither predictor fully captures alone. The composite targets supply chain spillovers reinforced by analyst attention.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": 0.5, "primitive": "AnalystRevision"},
        {"weight": 1.0, "primitive": "iomom_supp"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Overlooked Intangible Edge",
    "mechanism": "Firms with high intangible-related book-to-market ratios and organizational capital but low analyst coverage can be mispriced due to underappreciation of intangibles, especially when analysts are slow to recognize value. The composite exploits this informational inefficiency.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "IntanBM"},
        {"weight": 0.5, "primitive": "OrgCap"},
        {"weight": -0.5, "primitive": "ChNAnalyst"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "IntanBM", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.52,
    "expected_decay_half_life_months": 42
  },
  {
    "name": "Earnings Consistency–Volatility Disconnect",
    "mechanism": "Stocks with consistent earnings and low realized volatility, but high forecast dispersion, may be overlooked by simple quality or risk screens. This blend captures persistent mispricings when consensus lags despite financial stability.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "EarningsConsistency"},
        {"weight": 0.5, "primitive": "RealizedVol"},
        {"weight": -1.0, "primitive": "ForecastDispersion"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "correlation", "primitive": "EarningsConsistency", "bound": "below", "threshold": 0.3},
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "lower"},
      {"type": "size_segment", "segment": "mega", "direction": "weaker"}
    ],
    "expected_annualized_sharpe": 0.48,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Post-IPO Efficient Growth",
    "mechanism": "Firms that recently IPO’d and show high asset turnover while limiting subsequent equity issuance may benefit from lasting post-IPO underpricing and operational discipline, a channel distinct from generic growth or issuance effects.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AgeIPO"},
        {"weight": 0.5, "primitive": "ChAssetTurnover"},
        {"weight": -1.0, "primitive": "NetEquityFinance"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.56,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Unloved Seasonals",
    "mechanism": "Stocks demonstrating both off-season positive momentum and negative analyst forecast dispersion in low-volatility markets are likely to benefit from neglected information flow and underreaction to non-calendar news, creating a unique return source distinct from generic momentum.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "MomOffSeason"},
        {"weight": -1.0, "primitive": "ForecastDispersion"},
        {"weight": 0.5, "primitive": "VolumeTrend"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "subperiod_consistency"},
      {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.44,
    "expected_decay_half_life_months": 15
  },
  {
    "name": "Liquidity-driven Conglomerate Discount",
    "mechanism": "By combining negative price delay, high Amihud illiquidity, and conglomerate return, this composite isolates liquidity-driven mispricings in multi-business firms, going beyond standard illiquidity or conglomerate discount explanations.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "PriceDelayRsq"},
        {"weight": 1.0, "primitive": "Illiquidity"},
        {"weight": 0.5, "primitive": "retConglomerate"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "correlation", "primitive": "Illiquidity", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.58,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Defensive Franchise Value",
    "mechanism": "Firms with high brand capital investment, strong cash productivity, and low implied volatility are resilient to macro shocks and benefit from lasting franchise effects not fully captured by traditional quality or volatility screens.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BrandInvest"},
        {"weight": 0.5, "primitive": "CashProd"},
        {"weight": -1.0, "primitive": "CPVolSpread"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.50,
    "expected_decay_half_life_months": null
  }
]}
